#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n,m;
    cin>>n>>m;
    int a[10];
    for(int i=0;i<10;i++) cin>>a[i];
    vector<vector<int>> adj(n+1);
    for(int i=0;i<m;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
    }
    auto now=chrono::steady_clock::now;
    auto st=now();
    mt19937 rng(42);
    vector<int> best;
    // Try many random greedy paths
    while(chrono::duration_cast<chrono::milliseconds>(now()-st).count()<4500){
        int sv=rng()%n+1;
        vector<int> path;
        vector<bool> used(n+1,false);
        path.push_back(sv);
        used[sv]=true;
        while(true){
            int cur=path.back();
            // Collect unused neighbors
            vector<pair<int,int>> cands;
            for(int v:adj[cur]){
                if(!used[v]){
                    int deg=0;
                    for(int w:adj[v]) if(!used[w]) deg++;
                    cands.push_back({deg,v});
                }
            }
            if(cands.empty()) break;
            // Warnsdorff: pick among those with smallest degree, with some randomness
            sort(cands.begin(),cands.end());
            int lim=1;
            while(lim<(int)cands.size() && cands[lim].first==cands[0].first) lim++;
            // Sometimes pick randomly from top few
            int pick;
            if(rng()%4==0 && (int)cands.size()>1){
                pick=rng()%min((int)cands.size(),3);
            } else {
                pick=rng()%lim;
            }
            int nxt=cands[pick].second;
            path.push_back(nxt);
            used[nxt]=true;
        }
        if((int)path.size()>(int)best.size()) best=path;
        if((int)best.size()==n) break;
    }
    cout<<best.size()<<"\n";
    for(int i=0;i<(int)best.size();i++){
        if(i) cout<<' ';
        cout<<best[i];
    }
    cout<<"\n";
}
